#!/usr/bin/env python3
from pathlib import Path
import subprocess,tempfile,sys

work=Path(sys.argv[1] if len(sys.argv)>1 else 'work')
java=work/'project/app/src/main/java/it/darkroom/timer'
with tempfile.TemporaryDirectory() as td:
    td=Path(td);classes=td/'classes';classes.mkdir();src=td/'src';(src/'it/darkroom/timer/assistant/search').mkdir(parents=True);(src/'it/darkroom/timer').mkdir(parents=True,exist_ok=True)
    engine=java/'assistant/search/SmartSearchEngine.java';(src/'it/darkroom/timer/assistant/search/SmartSearchEngine.java').write_bytes(engine.read_bytes())
    test=src/'TestSmart.java';test.write_text('''import java.util.*; import it.darkroom.timer.assistant.search.SmartSearchEngine; public class TestSmart { static SmartSearchEngine.Item x(String id,String name,String maker,String[] cats,String[] aliases,boolean remote){return new SmartSearchEngine.Item(id,name,maker,Arrays.asList(cats),Arrays.asList(aliases),"","",name,remote);} static String first(List<SmartSearchEngine.Item> all,String q,String cat){List<SmartSearchEngine.Result> r=SmartSearchEngine.search(all,q,cat,8);if(r.isEmpty())throw new RuntimeException("no result "+q);return r.get(0).item.name;} public static void main(String[] a){List<SmartSearchEngine.Item> all=new ArrayList<>();all.add(x("fu","FOMA Universal","FOMA",new String[]{"FILM_DEVELOPER"},new String[]{"foma universal developer","foma un"},false));all.add(x("fur","FOMA Universal Extra","FOMA",new String[]{"FILM_DEVELOPER"},new String[]{"universal extra"},false));all.add(x("d76","KODAK D-76","KODAK",new String[]{"FILM_DEVELOPER"},new String[]{"d76","d-76","d 76"},false));all.add(x("hp5","ILFORD HP5 PLUS","ILFORD",new String[]{"FILM"},new String[]{"hp5","hp5+","hp 5"},false));all.add(x("trix","KODAK TRI-X 400","KODAK",new String[]{"FILM"},new String[]{"tri x","trix","tri-x"},false));for(String n:new String[]{"1510","1520","1540","2520","2540","2550"})all.add(x("j"+n,"JOBO "+n,"JOBO",new String[]{"TANK"},new String[]{n,"jobo "+n.substring(0,2)},false));all.add(x("online","FOMA Universal Online Extra","FOMA",new String[]{"FILM_DEVELOPER"},new String[]{"foma un"},true));if(!first(all,"foma un","FILM_DEVELOPER").equals("FOMA Universal"))throw new RuntimeException("foma un");if(!first(all,"FOMA UNIVERSAL","FILM_DEVELOPER").equals("FOMA Universal"))throw new RuntimeException("exact");for(String q:new String[]{"d76","d-76","d 76"})if(!first(all,q,"FILM_DEVELOPER").equals("KODAK D-76"))throw new RuntimeException(q);if(!first(all,"hp5","FILM").equals("ILFORD HP5 PLUS"))throw new RuntimeException("hp5");if(!first(all,"tri x","FILM").equals("KODAK TRI-X 400"))throw new RuntimeException("tri x");if(!first(all,"2520","TANK").equals("JOBO 2520"))throw new RuntimeException("2520");if(SmartSearchEngine.search(all,"jobo","TANK",8).size()<2)throw new RuntimeException("jobo");if(!first(all,"FOMA Universal","FILM_DEVELOPER").equals("FOMA Universal"))throw new RuntimeException("ranking");System.out.println("foma un -> FOMA Universal");System.out.println("d76/d-76/d 76 -> KODAK D-76");System.out.println("hp5 -> ILFORD HP5 PLUS; tri x -> KODAK TRI-X 400; 2520 -> JOBO 2520; jobo -> multiple: PASS");}}''',encoding='utf-8')
    subprocess.run(['javac','-d',str(classes),str(src/'it/darkroom/timer/assistant/search/SmartSearchEngine.java'),str(test)],check=True)
    out=subprocess.check_output(['java','-cp',str(classes),'TestSmart'],text=True);print(out,end='')

    (src/'it/darkroom/timer/TimingMath.java').write_bytes((java/'TimingMath.java').read_bytes());(src/'it/darkroom/timer/SplitGradePlan.java').write_bytes((java/'SplitGradePlan.java').read_bytes())
    split=src/'TestSplit.java';split.write_text('''import it.darkroom.timer.SplitGradePlan; public class TestSplit {public static void main(String[] a){SplitGradePlan p=new SplitGradePlan();if(p.softYellow!=60||p.hardMagenta!=180)throw new RuntimeException();if(!p.softPrompt().equals("Azzera il magenta e imposta giallo 60. Poi premi il pulsante."))throw new RuntimeException();if(!p.hardPrompt().equals("Azzera il giallo e imposta magenta 180. Poi premi il pulsante."))throw new RuntimeException();p.softYellow=50;p.hardMagenta=160;if(!p.softPrompt().contains("giallo 50.")||!p.hardPrompt().contains("magenta 160."))throw new RuntimeException();System.out.println("Split Grade defaults + dynamic TTS: PASS");}}''',encoding='utf-8')
    subprocess.run(['javac','-d',str(classes),str(src/'it/darkroom/timer/TimingMath.java'),str(src/'it/darkroom/timer/SplitGradePlan.java'),str(split)],check=True)
    print(subprocess.check_output(['java','-cp',str(classes),'TestSplit'],text=True),end='')
